    if(!$demos)echo '<div class="card empty">Las demostraciones todavía no están disponibles. Ejecuta la actualización desde el panel maestro.</div>';echo '</div><p class="demo-selector-return"><a class="btn btn-light" href="'.url().'">← Volver al sitio oficial</a></p></div></section></main>';public_footer();layout_end();
}

