function tenant_home(App $app,array $t):void{
    $content=$app->all('SELECT * FROM tenant_content WHERE tenant_id=? AND is_active=1 AND branch_id IS NULL ORDER BY section_key,sort_order',[$t['id']]);$slides=array_values(array_filter($content,fn($x)=>$x['section_key']==='home_slider'));$blocks=array_values(array_filter($content,fn($x)=>$x['section_key']==='home_block'));
    if(!$slides)$slides=[['title'=>'Todo lo que buscas','body'=>'Explora nuestro catálogo y envíanos tu pedido en pocos pasos.','image'=>url('assets/placeholder.svg')],['title'=>'Promociones para ti','body'=>'Descubre productos seleccionados y ofertas especiales.','image'=>url('assets/placeholder.svg')],['title'=>'Compra desde donde estés','body'=>'Rápido, claro y directo a nuestro WhatsApp.','image'=>url('assets/placeholder.svg')]];
    if(!$blocks)$blocks=[['title'=>'Calidad','body'=>'Productos seleccionados para nuestros clientes.','image'=>url('assets/placeholder.svg')],['title'=>'Atención cercana','body'=>'Haz tu pedido y conversemos por WhatsApp.','image'=>url('assets/placeholder.svg')],['title'=>'Entrega conveniente','body'=>'Elige tu zona y conoce el precio antes de enviar.','image'=>url('assets/placeholder.svg')]];
    layout_start('Inicio',$t);echo '<div data-tenant="'.e($t['slug']).'">';public_header($t);echo '<main><section class="hero"><div class="container"><div class="slider">';foreach($slides as $i=>$s)echo adaptive_slide_v1($s,$i,'linear-gradient(90deg,#111a,#1112)','<a class="btn btn-accent" href="'.url($t['slug'].'/'.catalog_segment($t)).'">Ver '.e($t['catalog_label']).'</a>');echo '<div class="slider-dots">';foreach($slides as $i=>$s)echo '<button class="slider-dot '.($i===0?'active':'').'" aria-label="Ir a diapositiva '.($i+1).'"></button>';echo '</div></div></div></section><section class="section"><div class="container"><div class="grid grid-3">';foreach(array_slice($blocks,0,3) as $b)echo '<article class="card feature"><img loading="lazy" src="'.e(public_media_url($b['image']??null)).'" alt="'.e($b['title']).'"><div class="card-body"><h3>'.e($b['title']).'</h3><p class="muted">'.e($b['body']).'</p></div></article>';echo '</div></div></section></main>';public_footer($t);echo '</div>';layout_end();
}

function catalog_page(App $app,array $t):void{
    $cats=$app->all('SELECT * FROM categories WHERE tenant_id=? AND is_active=1 ORDER BY sort_order,name',[$t['id']]);$products=$app->all("SELECT p.*,c.slug category_slug,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? AND p.status!='hidden' ORDER BY p.is_featured DESC,p.name",[$t['id']]);
    $promo=$app->all("SELECT * FROM tenant_content WHERE tenant_id=? AND section_key='catalog_slider' AND is_active=1 ORDER BY sort_order LIMIT 3",[$t['id']]);if(!$promo)$promo=[['title'=>$t['catalog_label'],'body'=>'Elige, agrega al carrito y envía tu pedido.','image'=>url('assets/placeholder.svg')]];
    layout_start($t['catalog_label'],$t);echo '<div data-tenant="'.e($t['slug']).'">';public_header($t,'catalogo');echo '<main><section class="hero catalog-hero"><div class="container"><div class="slider">';foreach($promo as $i=>$s)echo '<article class="slide '.($i===0?'active':'').'" style="background-image:linear-gradient(90deg,#0f4faadd,#25d36699),url(\''.e($s['image']?:url('assets/placeholder.svg')).'\')"><div class="slide-content"><h1>'.e($s['title']).'</h1><p>'.e($s['body']).'</p></div></article>';echo '<div class="slider-dots">';foreach($promo as $i=>$s)echo '<button class="slider-dot '.($i===0?'active':'').'" aria-label="Promoción '.($i+1).'"></button>';echo '</div></div><div class="catalog-toolbar"><input id="catalogSearch" class="search" placeholder="Buscar productos…" aria-label="Buscar productos"><div class="chips"><button class="chip active" data-category="all">Todos</button>';foreach($cats as $c)echo '<button class="chip" data-category="'.e($c['slug']).'">'.e($c['name']).'</button>';echo '</div></div><div class="grid grid-4">';
    if(!$products)echo '<div class="card empty">Todavía no hay productos publicados.</div>';foreach($products as $p){$price=(float)($p['sale_price']?:$p['price']);$data=json_encode(['id'=>(int)$p['id'],'name'=>$p['name'],'price'=>$price,'unit'=>$p['unit_label'],'min'=>(float)$p['min_qty'],'step'=>(float)$p['qty_step']],JSON_HEX_APOS|JSON_HEX_QUOT);echo '<article class="card product-card" data-product=\''.e($data).'\' data-search="'.e(strtolower($p['name'].' '.$p['description'].' '.$p['characteristics'])).'" data-category="'.e($p['category_slug']??'').'">';echo '<img class="product-img" loading="lazy" src="'.e($p['image']?:url('assets/placeholder.svg')).'" alt="'.e($p['name']).'"><div class="product-info">'.($p['badge']?'<span class="tag">'.e($p['badge']).'</span>':'').'<h3>'.e($p['name']).'</h3><p class="muted">'.e($p['description']).'</p>'.($p['characteristics']?'<ul class="product-features"><li>'.implode('</li><li>',array_map('e',array_filter(array_map('trim',preg_split('/\R/',(string)$p['characteristics']))))).'</li></ul>':'').'<div class="product-price">'.money($price).'</div><div class="product-meta">Por '.e($p['unit_label']).' · IVA '.e((string)$p['tax_rate']).'%</div><div class="qty-row"><input data-qty class="qty" type="number" min="'.e($p['min_qty']).'" step="'.e($p['qty_step']).'" value="'.e($p['min_qty']).'" '.($p['status']==='sold_out'?'disabled':'').'><button class="btn btn-block" data-add-cart '.($p['status']==='sold_out'?'disabled':'').'>'.($p['status']==='sold_out'?'Agotado':'Agregar').'</button></div></div></article>';}
    echo '</div></div></section></main>';cart_drawer($app,$t);public_footer($t);echo '</div>';layout_end();
}

function catalog_page_v5(App $app,array $t):void
{
    track_event_v1($app,(int)$t['id'],'catalog_view');
    $cats=$app->all('SELECT * FROM categories WHERE tenant_id=? AND is_active=1 ORDER BY sort_order,name',[$t['id']]);$products=$app->all("SELECT p.*,c.slug category_slug,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? AND p.status!='hidden' ORDER BY p.is_featured DESC,p.name",[$t['id']]);
    $optionRows=$app->all('SELECT g.product_id,g.id group_id,g.name group_name,g.type,g.is_required,g.min_select,g.max_select,o.id option_id,o.name option_name,o.price_delta FROM product_option_groups g JOIN product_options o ON o.group_id=g.id AND o.is_active=1 WHERE g.tenant_id=? AND g.is_active=1 ORDER BY g.product_id,g.sort_order,g.id,o.sort_order,o.id',[$t['id']]);$groupMap=[];foreach($optionRows as $row){$pid=(int)$row['product_id'];$gid=(int)$row['group_id'];if(!isset($groupMap[$pid][$gid]))$groupMap[$pid][$gid]=['id'=>$gid,'name'=>$row['group_name'],'type'=>$row['type'],'required'=>(bool)$row['is_required'],'min'=>(int)$row['min_select'],'max'=>(int)$row['max_select'],'options'=>[]];$groupMap[$pid][$gid]['options'][]=['id'=>(int)$row['option_id'],'name'=>$row['option_name'],'delta'=>(float)$row['price_delta']];}
    $promo=$app->all("SELECT * FROM tenant_content WHERE tenant_id=? AND section_key='catalog_slider' AND is_active=1 ORDER BY sort_order LIMIT 3",[$t['id']]);if(!$promo)$promo=[['title'=>$t['catalog_label'],'body'=>'Elige, personaliza y envía tu pedido.','image'=>url('assets/placeholder.svg')]];
    layout_start($t['catalog_label'],$t);echo '<div data-tenant="'.e($t['slug']).'">';public_header($t,'catalogo');echo '<main>';if($t['slug']==='tienda-demo')echo '<section class="demo-access"><div class="container demo-access-inner"><div><span class="tag">DEMO INTERACTIVA</span><strong>Prueba compras, variantes y pedidos sin enviar WhatsApp real.</strong></div><div class="demo-credentials"><span>Cliente: <b>cliente.demo@fisitaap.com</b></span><span>Clave: <b>DemoCliente2026!</b></span><span>Cupón: <b>NOVA10</b></span></div></div></section>';echo '<section class="hero catalog-hero"><div class="container"><div class="slider">';foreach($promo as $i=>$slide)echo '<article class="slide '.($i===0?'active':'').'" style="background-image:linear-gradient(90deg,#0b1d32dd,#0b7a5588),url(\''.e(public_media_url($slide['image']??null)).'\')"><div class="slide-content"><h1>'.e($slide['title']).'</h1><p>'.e($slide['body']).'</p></div></article>';echo '<div class="slider-dots">';foreach($promo as $i=>$slide)echo '<button class="slider-dot '.($i===0?'active':'').'" aria-label="Promoción '.($i+1).'"></button>';echo '</div></div><div class="catalog-toolbar"><input id="catalogSearch" class="search" placeholder="Buscar productos…" aria-label="Buscar productos"><div class="chips"><button class="chip active" data-category="all">Todos</button>';foreach($cats as $category)echo '<button class="chip" data-category="'.e($category['slug']).'">'.e($category['name']).'</button>';echo '</div></div><div class="grid grid-4">';
    if(!$products)echo '<div class="card empty">Todavía no hay productos publicados.</div>';
    foreach($products as $product){$price=(float)($product['sale_price']?:$product['price']);$groups=array_values($groupMap[(int)$product['id']]??[]);$data=json_encode(['id'=>(int)$product['id'],'name'=>$product['name'],'price'=>$price,'unit'=>$product['unit_label'],'min'=>(float)$product['min_qty'],'step'=>(float)$product['qty_step'],'groups'=>$groups],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);$gallery=json_decode((string)($product['gallery']??'[]'),true)?:[];$images=array_values(array_unique(array_map('public_media_url',array_filter(array_merge([$product['image']?:url('assets/placeholder.svg')],$gallery)))));echo '<article class="card product-card" data-product=\''.e($data).'\' data-search="'.e(strtolower($product['name'].' '.$product['description'].' '.$product['characteristics'])).'" data-category="'.e($product['category_slug']??'').'">';echo '<div class="product-gallery"><img class="product-img" data-gallery-main loading="lazy" src="'.e($images[0]).'" alt="'.e($product['name']).'">';if(count($images)>1){echo '<div class="product-thumbs">';foreach($images as $i=>$image)echo '<button type="button" class="product-thumb '.($i===0?'active':'').'" data-gallery-src="'.e($image).'" aria-label="Imagen '.($i+1).'"><img src="'.e($image).'" alt=""></button>';echo '</div>';}echo '</div><div class="product-info">'.($product['badge']?'<span class="tag">'.e($product['badge']).'</span>':'').(($product['product_type']??'simple')==='combo'?'<span class="tag combo-tag">COMBO</span>':'').'<h3>'.e($product['name']).'</h3><p class="muted">'.e($product['description']).'</p>'.($product['characteristics']?'<ul class="product-features"><li>'.implode('</li><li>',array_map('e',array_filter(array_map('trim',preg_split('/\R/',(string)$product['characteristics']))))).'</li></ul>':'').'<div class="product-price">'.money($price).'</div><div class="product-meta">Por '.e($product['unit_label']).' · IVA '.e((string)$product['tax_rate']).'%</div><div class="qty-row"><input data-qty class="qty" type="number" min="'.e($product['min_qty']).'" step="'.e($product['qty_step']).'" value="'.e($product['min_qty']).'" '.($product['status']==='sold_out'?'disabled':'').'><button class="btn btn-block" '.($groups?'data-customize-cart':'data-add-cart').' '.($product['status']==='sold_out'?'disabled':'').'>'.($product['status']==='sold_out'?'Agotado':'Agregar al carrito').'</button></div></div></article>';}
    echo '</div></div></section></main>';cart_drawer($app,$t);echo '<div id="productCustomizer" class="product-modal" aria-hidden="true"><div class="product-modal-bg" data-close-customizer></div><section class="card product-modal-panel"><div class="drawer-head"><div><span class="tag">PERSONALIZAR</span><h2 id="customizerTitle">Producto</h2></div><button class="icon-btn" type="button" data-close-customizer>×</button></div><div id="customizerGroups"></div><div class="form-group"><label>Observaciones para este producto</label><textarea id="customizerNote" class="input" maxlength="500" placeholder="Ejemplo: sin cebolla, salsa aparte…"></textarea></div><div class="split"><div class="form-group"><label>Cantidad</label><input id="customizerQty" class="input" type="number"></div><div class="customizer-total"><small>Total unitario</small><strong id="customizerPrice">₡0,00</strong></div></div><button id="customizerAdd" type="button" class="btn btn-accent btn-block">Agregar al carrito</button></section></div>';public_footer($t);echo '</div>';layout_end();
}

function cart_drawer(App $app,array $t):void{
    $zones=$app->all('SELECT * FROM delivery_zones WHERE tenant_id=? AND is_active=1 ORDER BY name',[$t['id']]);
    $paymentMethods=json_decode((string)($t['payment_methods']??''),true)?:['SINPE Móvil','Efectivo','Tarjeta al recibir','Transferencia'];$deliveryTypes=json_decode((string)($t['delivery_types']??''),true)?:['delivery','pickup','coordinated'];$paymentHtml='';foreach($paymentMethods as $method)$paymentHtml.='<option>'.e($method).'</option>';$deliveryHtml='';foreach(['delivery'=>'Delivery','pickup'=>'Recoger en el negocio','coordinated'=>'Envío coordinado'] as $key=>$label)if(in_array($key,$deliveryTypes,true))$deliveryHtml.='<option value="'.$key.'">'.$label.'</option>';
    $user=current_user();$addresses=$user&&$user['role']==='customer'?$app->all('SELECT * FROM customer_addresses WHERE user_id=? ORDER BY is_default DESC,id DESC',[$user['id']]):[];
    echo '<aside id="cartDrawer" class="drawer"><div class="drawer-bg" data-close-cart></div><div class="drawer-panel"><div class="drawer-head"><h2>Tu pedido</h2><button class="icon-btn" data-close-cart>×</button></div><div id="cartItems"></div><div class="cart-summary"><div class="summary-row"><span>Subtotal estimado</span><strong id="cartSubtotal">₡0,00</strong></div><small class="muted">IVA, descuento y entrega se calculan al confirmar.</small></div><form id="checkoutForm" action="'.url('api/checkout').'">'.csrf_field().'<input type="hidden" name="tenant" value="'.e($t['slug']).'"><div class="form-group"><label>Cédula (opcional)</label><input class="input" name="customer_id_number" maxlength="40"></div><div class="form-group"><label>Forma de pago</label><select class="input" name="payment" required>'.$paymentHtml.'</select></div><div class="form-group"><label>Tipo de entrega</label><select class="input" name="delivery_type">'.$deliveryHtml.'</select></div><div class="form-group"><label>Zona de envío</label><select class="input" name="zone_id"><option value="">Seleccionar</option>';foreach($zones as $z)echo '<option value="'.(int)$z['id'].'">'.e($z['name']).' · '.money((float)$z['price']).'</option>';echo '</select></div>';if($addresses){echo '<div class="form-group"><label>Dirección guardada</label><select class="input" data-saved-address><option value="">Escribir otra dirección</option>';foreach($addresses as $a)echo '<option value="'.e(json_encode(['address'=>$a['address'],'reference'=>$a['reference']],JSON_HEX_APOS|JSON_HEX_QUOT)).'">'.e($a['label']).' · '.e($a['address']).'</option>';echo '</select></div>';}echo '<div class="form-group"><label>Dirección</label><textarea class="input" name="address" placeholder="Provincia, cantón y distrito"></textarea></div><div class="form-group"><label>Referencia</label><textarea class="input" name="address_reference" placeholder="Señas para llegar"></textarea></div><div class="form-group"><label>Programar pedido (opcional)</label><input class="input" type="datetime-local" name="scheduled_at" min="'.date('Y-m-d\TH:i').'"></div><div class="form-group"><label>Código de descuento</label><input class="input" name="coupon" maxlength="60"></div><div class="form-group"><label>Notas</label><textarea class="input" name="notes" placeholder="Detalles para el negocio"></textarea></div><button class="btn btn-accent btn-block" type="submit">Enviar pedido por WhatsApp</button></form></div></aside>';
}

function checkout_api(App $app):never{
    $raw=json_decode(file_get_contents('php://input'),true)?:[];$_POST=$raw+$_POST;verify_csrf();$u=current_user();if(!$u||$u['role']!=='customer')json_response(['ok'=>false,'login'=>url('login?next='.rawurlencode($_SERVER['HTTP_REFERER']??url()))],401);
    if(!rate_limit_persistent($app,'checkout',client_identity((string)$u['id']),10,300))json_response(['ok'=>false,'error'=>'Demasiados intentos. Espera unos minutos.'],429);
    $t=tenant_by_slug($app,(string)($raw['tenant']??''));if(!$t||!$t['is_active'])json_response(['ok'=>false,'error'=>'Tienda no disponible.'],404);$items=$raw['items']??[];if(!$items||count($items)>100)json_response(['ok'=>false,'error'=>'Carrito inválido.'],422);
    $deliveryType=(string)($raw['delivery_type']??'delivery');$payment=(string)($raw['payment']??'');$address=trim((string)($raw['address']??''));
    if(!in_array($deliveryType,['delivery','pickup','coordinated'],true))json_response(['ok'=>false,'error'=>'Tipo de entrega inválido.'],422);
    if(!in_array($payment,['SINPE Móvil','Efectivo','Tarjeta al recibir','Transferencia'],true))json_response(['ok'=>false,'error'=>'Forma de pago inválida.'],422);
    if($deliveryType==='delivery'&&$address==='')json_response(['ok'=>false,'error'=>'Escribe la dirección completa para el delivery.'],422);
    $ids=array_values(array_unique(array_map('intval',array_column($items,'id'))));$ph=implode(',',array_fill(0,count($ids),'?'));$products=$app->all("SELECT * FROM products WHERE tenant_id=? AND status='active' AND id IN ($ph)",array_merge([$t['id']],$ids));$map=[];foreach($products as $p)$map[$p['id']]=$p;if(count($map)!==count($ids))json_response(['ok'=>false,'error'=>'Uno o más productos ya no están disponibles.'],422);
    $subtotal=0;$tax=0;$lines=[];foreach($items as $i){$p=$map[(int)$i['id']];$q=round((float)$i['qty'],(int)$p['decimals']);$min=(float)$p['min_qty'];$step=(float)$p['qty_step'];$steps=($q-$min)/$step;if($q<$min||$q>99999||abs($steps-round($steps))>0.0001)json_response(['ok'=>false,'error'=>'Cantidad inválida para '.$p['name']],422);$price=(float)($p['sale_price']?:$p['price']);$line=$price*$q;$lineTax=$line*((float)$p['tax_rate']/100);$subtotal+=$line;$tax+=$lineTax;$lines[]=[$p,$q,$price,$line,$lineTax];}
    $zoneTotal=0;$zone=null;if($deliveryType==='delivery'){if(empty($raw['zone_id']))json_response(['ok'=>false,'error'=>'Selecciona una zona de envío.'],422);$zone=$app->one('SELECT * FROM delivery_zones WHERE id=? AND tenant_id=? AND is_active=1',[(int)$raw['zone_id'],$t['id']]);if(!$zone)json_response(['ok'=>false,'error'=>'Zona inválida.'],422);if($subtotal<(float)$zone['min_order'])json_response(['ok'=>false,'error'=>'Esta zona requiere una compra mínima de '.money((float)$zone['min_order'])],422);$zoneTotal=(float)$zone['price'];}
    $discount=0;$couponCode=strtoupper(trim((string)($raw['coupon']??'')));$number='';$total=0;
    $app->db->beginTransaction();try{
        if($couponCode){$c=$app->one("SELECT * FROM coupons WHERE tenant_id=? AND code=? AND is_active=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) FOR UPDATE",[$t['id'],$couponCode]);if(!$c||($c['max_uses']!==null&&(int)$c['uses_count']>=(int)$c['max_uses'])||$subtotal<(float)$c['min_order'])throw new DomainException('El cupón no es válido para este pedido.');$discount=$c['type']==='percent'?min($subtotal,$subtotal*((float)$c['value']/100)):min($subtotal,(float)$c['value']);}
        $total=$subtotal+$tax+$zoneTotal-$discount;
        $app->exec('INSERT INTO order_sequences(tenant_id,next_number) SELECT ?,COALESCE(MAX(CAST(order_number AS UNSIGNED)),0)+1 FROM orders WHERE tenant_id=? ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id)',[$t['id'],$t['id']]);
        $seq=$app->one('SELECT next_number FROM order_sequences WHERE tenant_id=? FOR UPDATE',[$t['id']]);$next=(int)$seq['next_number'];$app->exec('UPDATE order_sequences SET next_number=next_number+1 WHERE tenant_id=?',[$t['id']]);$number=str_pad((string)$next,5,'0',STR_PAD_LEFT);
        $app->exec('INSERT INTO orders(tenant_id,user_id,order_number,customer_name,customer_phone,address,delivery_zone_id,delivery_type,payment_method,coupon_code,subtotal,tax_total,discount_total,delivery_total,total,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$t['id'],$u['id'],$number,$u['name'],$u['phone']??'',$address,$zone['id']??null,$deliveryType,$payment,$couponCode?:null,$subtotal,$tax,$discount,$zoneTotal,$total,substr((string)($raw['notes']??''),0,1000)]);$oid=(int)$app->db->lastInsertId();foreach($lines as [$p,$q,$price,$line,$lineTax])$app->exec('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_label,unit_price,tax_rate,line_subtotal,line_tax) VALUES(?,?,?,?,?,?,?,?,?)',[$oid,$p['id'],$p['name'],$q,$p['unit_label'],$price,$p['tax_rate'],$line,$lineTax]);if($couponCode)$app->exec('UPDATE coupons SET uses_count=uses_count+1 WHERE tenant_id=? AND code=?',[$t['id'],$couponCode]);$app->db->commit();
    }catch(DomainException $e){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>$e->getMessage()],422);}catch(Throwable){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>'No se pudo guardar el pedido. Intenta nuevamente.'],500);}
    $msg="🛒 NUEVO PEDIDO #{$number}\n📅 ".date('d/m/Y - H:i')." hs\n👤 Cliente: {$u['name']}\n📱 Tel: ".($u['phone']??'')."\n📍 Dirección: {$address}\n━━ PRODUCTOS ━━\n";foreach($lines as [$p,$q,$price,$line])$msg.="• ".rtrim(rtrim(number_format($q,3,'.',''),'0'),'.')." {$p['unit_label']} {$p['name']} — ".money($line)."\n";$msg.="━━━━\nSubtotal: ".money($subtotal)."\nIVA: ".money($tax)."\nDescuento: -".money($discount)."\nEntrega: ".money($zoneTotal)."\nTOTAL: ".money($total)."\n💳 Pago: {$payment}\n🚚 Entrega: ".($zone['name']??($deliveryType==='pickup'?'Recoger en el negocio':'Envío coordinado'));$wa=preg_replace('/\D+/','',$t['whatsapp']?:$t['phone']);json_response(['ok'=>true,'order'=>$number,'whatsapp'=>'https://wa.me/'.$wa.'?text='.rawurlencode($msg)]);
}

function checkout_api_v5(App $app):never
{
    $raw=json_decode(file_get_contents('php://input'),true)?:[];$_POST=$raw+$_POST;verify_csrf();$user=current_user();if($user&&$user['role']!=='customer')json_response(['ok'=>false,'error'=>'Para comprar, cierra tu sesión administrativa e ingresa con una cuenta de cliente.'],403);if(!$user){$next=safe_next_url_v1($app,(string)($_SERVER['HTTP_REFERER']??''));json_response(['ok'=>false,'login'=>url('login'.($next?'?next='.rawurlencode($next):''))],401);}
    if(!rate_limit_persistent($app,'checkout',client_identity((string)$user['id']),10,300))json_response(['ok'=>false,'error'=>'Demasiados intentos. Espera unos minutos.'],429);
    $tenant=tenant_by_slug($app,(string)($raw['tenant']??''));if(!$tenant||!$tenant['is_active'])json_response(['ok'=>false,'error'=>'Tienda no disponible.'],404);$items=$raw['items']??[];if(!is_array($items)||!$items||count($items)>100)json_response(['ok'=>false,'error'=>'Carrito inválido.'],422);
    $deliveryType=(string)($raw['delivery_type']??'delivery');$payment=(string)($raw['payment']??'');$address=trim((string)($raw['address']??''));$reference=trim(substr(strip_tags((string)($raw['address_reference']??'')),0,500));$idNumber=trim(substr(strip_tags((string)($raw['customer_id_number']??'')),0,40));$scheduledAt=null;if(!empty($raw['scheduled_at'])){$scheduled=strtotime((string)$raw['scheduled_at']);if($scheduled===false||$scheduled<time()-60||$scheduled>strtotime('+90 days'))json_response(['ok'=>false,'error'=>'La fecha programada no es válida.'],422);$scheduledAt=date('Y-m-d H:i:s',$scheduled);}$allowedDeliveries=json_decode((string)($tenant['delivery_types']??''),true)?:['delivery','pickup','coordinated'];$allowedPayments=json_decode((string)($tenant['payment_methods']??''),true)?:['SINPE Móvil','Efectivo','Tarjeta al recibir','Transferencia'];if(!in_array($deliveryType,$allowedDeliveries,true))json_response(['ok'=>false,'error'=>'Tipo de entrega inválido.'],422);if(!in_array($payment,$allowedPayments,true))json_response(['ok'=>false,'error'=>'Forma de pago inválida.'],422);if($deliveryType==='delivery'&&$address==='')json_response(['ok'=>false,'error'=>'Escribe la dirección completa para el delivery.'],422);
    $ids=array_values(array_unique(array_filter(array_map('intval',array_column($items,'id')))));if(!$ids)json_response(['ok'=>false,'error'=>'Carrito inválido.'],422);$placeholders=implode(',',array_fill(0,count($ids),'?'));$products=$app->all("SELECT * FROM products WHERE tenant_id=? AND status='active' AND id IN ($placeholders)",array_merge([$tenant['id']],$ids));$productMap=[];foreach($products as $product)$productMap[(int)$product['id']]=$product;if(count($productMap)!==count($ids))json_response(['ok'=>false,'error'=>'Uno o más productos ya no están disponibles.'],422);
    $rows=$app->all("SELECT g.product_id,g.id group_id,g.name group_name,g.type,g.is_required,g.min_select,g.max_select,o.id option_id,o.name option_name,o.price_delta FROM product_option_groups g LEFT JOIN product_options o ON o.group_id=g.id AND o.is_active=1 WHERE g.tenant_id=? AND g.is_active=1 AND g.product_id IN ($placeholders) ORDER BY g.product_id,g.sort_order,g.id,o.sort_order,o.id",array_merge([$tenant['id']],$ids));$groups=[];$optionLookup=[];foreach($rows as $row){$pid=(int)$row['product_id'];$gid=(int)$row['group_id'];if(!isset($groups[$pid][$gid]))$groups[$pid][$gid]=['id'=>$gid,'name'=>$row['group_name'],'type'=>$row['type'],'min'=>(int)$row['min_select'],'max'=>(int)$row['max_select'],'required'=>(bool)$row['is_required'],'options'=>[]];if($row['option_id']!==null){$oid=(int)$row['option_id'];$option=['id'=>$oid,'group_id'=>$gid,'group'=>$row['group_name'],'name'=>$row['option_name'],'delta'=>(float)$row['price_delta']];$groups[$pid][$gid]['options'][$oid]=$option;$optionLookup[$pid][$oid]=$option;}}
    $subtotal=0.0;$tax=0.0;$lines=[];foreach($items as $item){if(!is_array($item))json_response(['ok'=>false,'error'=>'Carrito inválido.'],422);$pid=(int)($item['id']??0);if(!isset($productMap[$pid]))json_response(['ok'=>false,'error'=>'Producto no disponible.'],422);$product=$productMap[$pid];$quantity=round((float)($item['qty']??0),(int)$product['decimals']);$minimum=(float)$product['min_qty'];$step=(float)$product['qty_step'];$steps=($quantity-$minimum)/$step;if($quantity<$minimum||$quantity>99999||abs($steps-round($steps))>0.0001)json_response(['ok'=>false,'error'=>'Cantidad inválida para '.$product['name']],422);
