        foreach($groups[$pid]??[] as $group){$count=count($selectedByGroup[$group['id']]??[]);$min=$group['required']?max(1,$group['min']):$group['min'];$max=$group['type']==='single'?1:max(1,$group['max']);if($count<$min||$count>$max)json_response(['ok'=>false,'error'=>'Revisa la selección de '.$group['name'].' en '.$product['name'].'.'],422);}
