    }
    $zoneTotal=0.0;$zone=null;if($deliveryType==='delivery'){if(empty($raw['zone_id']))json_response(['ok'=>false,'error'=>'Selecciona una zona de envío.'],422);$zone=$app->one('SELECT * FROM delivery_zones WHERE id=? AND tenant_id=? AND is_active=1',[(int)$raw['zone_id'],$tenant['id']]);if(!$zone)json_response(['ok'=>false,'error'=>'Zona inválida.'],422);if($subtotal<(float)$zone['min_order'])json_response(['ok'=>false,'error'=>'Esta zona requiere una compra mínima de '.money((float)$zone['min_order'])],422);$zoneTotal=(float)$zone['price'];}
    $discount=0.0;$couponCode=strtoupper(trim((string)($raw['coupon']??'')));$number='';$total=0.0;$app->db->beginTransaction();try{if($couponCode){$coupon=$app->one("SELECT * FROM coupons WHERE tenant_id=? AND code=? AND is_active=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) FOR UPDATE",[$tenant['id'],$couponCode]);if(!$coupon||($coupon['max_uses']!==null&&(int)$coupon['uses_count']>=(int)$coupon['max_uses'])||$subtotal<(float)$coupon['min_order'])throw new DomainException('El cupón no es válido para este pedido.');$discount=$coupon['type']==='percent'?min($subtotal,$subtotal*((float)$coupon['value']/100)):min($subtotal,(float)$coupon['value']);}$total=$subtotal+$tax+$zoneTotal-$discount;
        $app->exec('INSERT INTO order_sequences(tenant_id,next_number) SELECT ?,COALESCE(MAX(CAST(order_number AS UNSIGNED)),0)+1 FROM orders WHERE tenant_id=? ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id)',[$tenant['id'],$tenant['id']]);$sequence=$app->one('SELECT next_number FROM order_sequences WHERE tenant_id=? FOR UPDATE',[$tenant['id']]);$next=(int)$sequence['next_number'];$app->exec('UPDATE order_sequences SET next_number=next_number+1 WHERE tenant_id=?',[$tenant['id']]);$number=str_pad((string)$next,5,'0',STR_PAD_LEFT);
        $app->exec('INSERT INTO orders(tenant_id,user_id,order_number,customer_name,customer_phone,customer_id_number,address,address_reference,scheduled_at,delivery_zone_id,delivery_type,payment_method,coupon_code,subtotal,tax_total,discount_total,delivery_total,total,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$tenant['id'],$user['id'],$number,$user['name'],$user['phone']??'',$idNumber?:null,$address,$reference?:null,$scheduledAt,$zone['id']??null,$deliveryType,$payment,$couponCode?:null,$subtotal,$tax,$discount,$zoneTotal,$total,substr((string)($raw['notes']??''),0,1000)]);$orderId=(int)$app->db->lastInsertId();foreach($lines as $line){$product=$line['product'];$app->exec('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_label,unit_price,tax_rate,line_subtotal,line_tax,options_json,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$orderId,$product['id'],$product['name'],$line['quantity'],$product['unit_label'],$line['price'],$product['tax_rate'],$line['subtotal'],$line['tax'],$line['options']?json_encode($line['options'],JSON_UNESCAPED_UNICODE):null,$line['note']?:null]);}if($couponCode)$app->exec('UPDATE coupons SET uses_count=uses_count+1 WHERE tenant_id=? AND code=?',[$tenant['id'],$couponCode]);$app->db->commit();track_event_v1($app,(int)$tenant['id'],'checkout_completed');
    }catch(DomainException $exception){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>$exception->getMessage()],422);}catch(Throwable){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>'No se pudo guardar el pedido. Intenta nuevamente.'],500);}
    $message="🛒 NUEVO PEDIDO #{$number}\n📅 ".date('d/m/Y - H:i')." hs".($scheduledAt?"\n⏰ Programado: ".date('d/m/Y H:i',strtotime($scheduledAt)):"")."\n👤 Cliente: {$user['name']}".($idNumber?"\n🪪 Cédula: {$idNumber}":"")."\n📱 Tel: ".($user['phone']??'')."\n📍 Dirección: {$address}".($reference?"\n🧭 Referencia: {$reference}":"")."\n━━ PRODUCTOS ━━\n";foreach($lines as $line){$product=$line['product'];$message.='• '.rtrim(rtrim(number_format($line['quantity'],3,'.',''),'0'),'.').' '.$product['unit_label'].' '.$product['name'].' — '.money($line['subtotal'])."\n";foreach($line['options'] as $option)$message.='   ↳ '.$option['group'].': '.$option['name'].($option['delta']>0?' (+'.money((float)$option['delta']).')':'')."\n";if($line['note'])$message.='   Nota: '.$line['note']."\n";}$message.="━━━━\nSubtotal: ".money($subtotal)."\nIVA: ".money($tax)."\nDescuento: -".money($discount)."\nEntrega: ".money($zoneTotal)."\nTOTAL: ".money($total)."\n💳 Pago: {$payment}\n🚚 Entrega: ".($zone['name']??($deliveryType==='pickup'?'Recoger en el negocio':'Envío coordinado'));$whatsapp=preg_replace('/\D+/','',$tenant['whatsapp']?:$tenant['phone']);$isDemo=$tenant['slug']==='tienda-demo';json_response(['ok'=>true,'order'=>$number,'order_id'=>$orderId,'demo'=>$isDemo,'store'=>$tenant['name'],'preview'=>$isDemo?$message:null,'whatsapp'=>'https://wa.me/'.$whatsapp.'?text='.rawurlencode($message)]);
}

function blog_page(App $app,array $t):void{$posts=$app->all("SELECT p.*,u.name author FROM posts p JOIN users u ON u.id=p.author_id WHERE p.tenant_id=? AND p.status='published' ORDER BY COALESCE(p.published_at,p.created_at) DESC",[$t['id']]);layout_start('Blog',$t);public_header($t);echo '<main class="section section-soft"><div class="container"><div class="section-head"><div><span class="tag">NOVEDADES</span><h2>Blog</h2></div></div>';if(!$posts)echo '<div class="card empty">Pronto compartiremos novedades.</div>';foreach($posts as $p){echo '<article class="card post">';if($p['media_url']&&$p['media_type']==='image')echo '<img class="post-media" loading="lazy" src="'.e($p['media_url']).'" alt="">';if($p['media_url']&&in_array($p['media_type'],['video','link']))echo '<div class="post-body"><a class="btn btn-light" target="_blank" rel="noopener" href="'.e($p['media_url']).'">Ver contenido</a></div>';echo '<div class="post-body"><p>'.nl2br(e($p['body'])).'</p><small class="muted">'.e($p['author']).' · '.e(date('d/m/Y',strtotime($p['published_at']?:$p['created_at']))).'</small></div></article>';}echo '</div></main>';public_footer($t);layout_end();}

function global_blog_page(App $app):void{$posts=$app->all("SELECT p.*,u.name author FROM posts p JOIN users u ON u.id=p.author_id WHERE p.tenant_id IS NULL AND p.status='published' ORDER BY COALESCE(p.published_at,p.created_at) DESC");layout_start('Blog');public_header();echo '<main class="section section-soft"><div class="container"><div class="section-head"><div><span class="tag">FISITAPP</span><h2>Novedades</h2></div></div>';if(!$posts)echo '<div class="card empty">Pronto publicaremos novedades.</div>';foreach($posts as $p)echo '<article class="card post">'.($p['media_url']?'<img class="post-media" src="'.e($p['media_url']).'" alt="">':'').'<div class="post-body">'.nl2br(e($p['body'])).'<br><small class="muted">'.e($p['author']).'</small></div></article>';echo '</div></main>';public_footer();layout_end();}

function contact_page(App $app,array $t):void{if(is_post()){verify_csrf();if(!rate_limit_persistent($app,'contact',client_identity((string)$t['id']),5,600)){flash('error','Espera antes de enviar otro mensaje.');}else{$name=trim($_POST['name']??'');$msg=trim($_POST['message']??'');if($name&&$msg){$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'Contacto desde FISITAPP');$app->exec('INSERT INTO contacts(tenant_id,name,email,phone,subject,message) VALUES(?,?,?,?,?,?)',[$t['id'],$name,$email,trim($_POST['phone']??''),$subject,$msg]);if(filter_var($t['email'],FILTER_VALIDATE_EMAIL))send_mail_v1($app,$t['email'],'FISITAPP: '.str_replace(["\r","\n"],' ',$subject),"Nombre: $name\nCorreo: $email\nTeléfono: ".trim($_POST['phone']??'')."\n\n$msg",(int)$t['id']);flash('success','Mensaje recibido. Pronto te contactaremos.');}else flash('error','Completa los campos requeridos.');}redirect(url($t['slug'].'/contacto'));}layout_start('Contacto',$t);public_header($t);echo '<main class="section"><div class="container split"><section><span class="tag">CONTACTO</span><h1>Conversemos</h1><p class="muted">'.nl2br(e($t['address'])).'</p><p><strong>Teléfono:</strong> '.e($t['phone']).'<br><strong>Correo:</strong> '.e($t['email']).'</p>'.safe_map_embed($t['map_embed']).'</section><section class="card admin-card">';render_flashes();echo '<form method="post">'.csrf_field().'<div class="form-group"><label>Nombre *</label><input class="input" name="name" required maxlength="150"></div><div class="split"><div class="form-group"><label>Teléfono</label><input class="input" name="phone" maxlength="40"></div><div class="form-group"><label>Correo</label><input class="input" type="email" name="email"></div></div><div class="form-group"><label>Asunto</label><input class="input" name="subject" maxlength="190"></div><div class="form-group"><label>Mensaje *</label><textarea class="input" name="message" required maxlength="3000"></textarea></div><button class="btn btn-block">Enviar mensaje</button></form></section></div></main>';public_footer($t);layout_end();}

function safe_map_embed(?string $html):string{if(!$html)return '';if(!preg_match('/src=["\'](https:\/\/(?:www\.)?google\.com\/maps\/embed[^"\']*)["\']/i',$html,$m))return '';$src=e($m[1]);return '<div class="card" style="overflow:hidden"><iframe src="'.$src.'" width="100%" height="360" style="border:0" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe></div>';}

function auth_page(App $app,string $mode,string $audience='customer'):void
{
    $active=current_user();if($active&&!is_post())redirect(role_home_url_v1($app,$active));$next=safe_next_url_v1($app,(string)($_GET['next']??$_POST['next']??''));$route=$mode==='register'?'register':($audience==='owner'?'owner-login':($audience==='master'?'master-login':'login'.($audience==='any'?'?audience=any':'')));
    if(is_post()){
        verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));if(!rate_limit_persistent($app,'auth',client_identity($email),8,300)){flash('error','Demasiados intentos. Espera cinco minutos.');redirect(url($route.($next?(str_contains($route,'?')?'&':'?').'next='.rawurlencode($next):'')));}$password=(string)($_POST['password']??'');
        if($mode==='register'){$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||!$phone)flash('error','Completa los datos y utiliza una contraseña de al menos 10 caracteres.');elseif($app->one('SELECT id FROM users WHERE email=?',[$email]))flash('error','Este correo ya está registrado.');else{$app->exec('INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?,?)',[$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT),'customer']);$newUserId=(int)$app->db->lastInsertId();try{issue_email_verification_v1($app,$newUserId,$email);}catch(Throwable){}flash('success','Cuenta creada. Ahora inicia sesión.');redirect(url('login'.($next?'?next='.rawurlencode($next):'')));}}
        else{$user=$app->one('SELECT * FROM users WHERE email=? AND is_active=1',[$email]);$audienceOk=$user&&($audience==='any'||($audience==='customer'&&$user['role']==='customer')||($audience==='master'&&$user['role']==='master')||($audience==='owner'&&in_array($user['role'],['master','tenant_admin','manager','editor','kitchen','cashier','driver'],true)));if(!$audienceOk||!password_verify($password,(string)($user['password_hash']??''))){usleep(250000);flash('error',$audience==='owner'?'Acceso administrativo incorrecto.':($audience==='master'?'Acceso administrativo incorrecto.':'Correo o contraseña incorrectos.'));}else{session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'tenant_id'=>$user['tenant_id'],'name'=>$user['name'],'email'=>$user['email'],'phone'=>$user['phone'],'role'=>$user['role']];$app->exec('UPDATE users SET last_login_at=NOW() WHERE id=?',[$user['id']]);if(!empty($user['force_password_change']))redirect(url('change-password'));if($next&&$user['role']==='customer')redirect(url($next));redirect(role_home_url_v1($app,$user));}}
        redirect(url($route.($next?(str_contains($route,'?')?'&':'?').'next='.rawurlencode($next):'')));
    }
    $titles=['owner'=>'Acceso de negocios','master'=>'Acceso de negocios','customer'=>'Iniciar sesión','any'=>'Iniciar sesión'];$title=$mode==='register'?'Crear cuenta':$titles[$audience];$officialLogo=$app->setting('platform_logo',url('assets/fisitapp-logo.webp'));layout_start($title);echo '<main class="auth-page"><section class="card auth-card"><a class="brand auth-brand" href="'.url().'"><img src="'.e($officialLogo).'" alt="FISITAPP"></a><span class="auth-type">'.e($title).'</span><h1>'.($mode==='login'?'Bienvenido de nuevo':'Crea tu cuenta').'</h1><p class="muted">'.($audience==='owner'?'El sistema detectará automáticamente si tu cuenta es maestra, pertenece a un negocio o es de motorizado.':($audience==='master'?'El sistema detectará automáticamente tu panel.':'Compra en las tiendas de FISITAPP con una sola cuenta.')).'</p>';render_flashes();echo '<form method="post">'.csrf_field().'<input type="hidden" name="next" value="'.e($next??'').'">';if($mode==='register')echo '<div class="form-group"><label>Nombre</label><input class="input" name="name" required maxlength="150"></div><div class="form-group"><label>Teléfono</label><input class="input" name="phone" required maxlength="40"></div>';echo '<div class="form-group"><label>Correo</label><input class="input" type="email" name="email" required autocomplete="email"></div><div class="form-group"><label>Contraseña</label><input class="input" type="password" name="password" required minlength="'.($mode==='register'?'10':'1').'" autocomplete="'.($mode==='register'?'new-password':'current-password').'"></div><button class="btn btn-block">'.($mode==='login'?'Ingresar':'Crear cuenta').'</button></form>'.($mode==='login'?'<p class="muted auth-links"><a href="'.url('forgot-password').'">¿Olvidaste tu contraseña?</a></p>':'').($audience==='owner'?'<p class="muted auth-links">¿Trabajas haciendo entregas? <a href="'.url('driver-register').'">Crear perfil de motorizado</a></p>':'').($audience==='customer'?'<p class="muted auth-links">'.($mode==='login'?'¿No tienes cuenta? <a href="'.url('register'.($next?'?next='.rawurlencode($next):'')).'">Crear usuario</a>':'¿Ya tienes cuenta? <a href="'.url('login'.($next?'?next='.rawurlencode($next):'')).'">Iniciar sesión</a>').'</p>':'').'</section></main>';layout_end();
}

function change_password_page(App $app):void{$u=require_login();if(is_post()){verify_csrf();$p=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');if(strlen($p)<12||$p!==$confirm)flash('error','Las contraseñas deben coincidir y tener al menos 12 caracteres.');else{$app->exec('UPDATE users SET password_hash=?,force_password_change=0 WHERE id=?',[password_hash($p,PASSWORD_DEFAULT),$u['id']]);flash('success','Contraseña actualizada.');redirect($u['role']==='master'?url('master'):($u['role']==='customer'?url('account'):($u['role']==='driver'?url('driver'):url('admin'))));}redirect(url('change-password'));}layout_start('Cambiar contraseña');echo '<main class="auth-page"><section class="card auth-card"><h1>Crea una contraseña nueva</h1><p class="muted">Este acceso era temporal. Define una contraseña privada antes de continuar.</p>';render_flashes();echo '<form method="post">'.csrf_field().'<div class="form-group"><label>Nueva contraseña</label><input class="input" type="password" name="password" minlength="12" required autocomplete="new-password"></div><div class="form-group"><label>Confirmar contraseña</label><input class="input" type="password" name="confirm" minlength="12" required autocomplete="new-password"></div><button class="btn btn-block">Guardar contraseña</button></form></section></main>';layout_end();}

function repeat_order_item_v5(App $app,array $item,int $tenantId):?array
{
    if(empty($item['product_id'])||($item['product_status']??'')!=='active')return null;$productId=(int)$item['product_id'];$stored=json_decode((string)($item['options_json']??''),true);$stored=is_array($stored)?$stored:[];$selectedIds=array_values(array_unique(array_map('intval',array_column($stored,'id'))));sort($selectedIds);
    $rows=$app->all('SELECT g.id group_id,g.name group_name,g.type,g.is_required,g.min_select,g.max_select,o.id option_id,o.name option_name,o.price_delta FROM product_option_groups g LEFT JOIN product_options o ON o.group_id=g.id AND o.is_active=1 WHERE g.product_id=? AND g.tenant_id=? AND g.is_active=1 ORDER BY g.sort_order,g.id,o.sort_order,o.id',[$productId,$tenantId]);$groups=[];$lookup=[];foreach($rows as $row){$gid=(int)$row['group_id'];if(!isset($groups[$gid]))$groups[$gid]=['type'=>$row['type'],'required'=>(bool)$row['is_required'],'min'=>(int)$row['min_select'],'max'=>(int)$row['max_select']];if($row['option_id']!==null)$lookup[(int)$row['option_id']]=['id'=>(int)$row['option_id'],'groupId'=>$gid,'group'=>$row['group_name'],'name'=>$row['option_name'],'delta'=>(float)$row['price_delta']];}
    $selected=[];$counts=[];$delta=0.0;foreach($selectedIds as $id){if(!isset($lookup[$id]))return null;$option=$lookup[$id];$selected[]=$option;$counts[$option['groupId']]=($counts[$option['groupId']]??0)+1;$delta+=$option['delta'];}foreach($groups as $gid=>$group){$count=$counts[$gid]??0;$min=$group['required']?max(1,$group['min']):$group['min'];$max=$group['type']==='single'?1:max(1,$group['max']);if($count<$min||$count>$max)return null;}
    $note=(string)($item['notes']??'');$price=(float)($item['current_sale_price']?:$item['current_price'])+$delta;$key=$productId.':'.implode(',',array_map(fn($option)=>(string)$option['id'],$selected)).':'.strtolower($note);return ['id'=>$productId,'name'=>$item['product_name'],'price'=>$price,'unit'=>$item['unit_label'],'min'=>(float)$item['min_qty'],'step'=>(float)$item['qty_step'],'options'=>$selected,'option_ids'=>$selectedIds,'note'=>$note,'key'=>$key,'qty'=>(float)$item['quantity']];
}

function customer_account_page(App $app):void
{
    $sessionUser=require_login(['customer']);$user=$app->one('SELECT id,name,email,phone FROM users WHERE id=? AND role="customer"',[$sessionUser['id']]);if(!$user){$_SESSION=[];redirect(url());}
    if(is_post()){
        verify_csrf();$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));
        if($name===''||$phone==='')flash('error','Nombre y teléfono son obligatorios.');
        else{$app->exec('UPDATE users SET name=?,phone=? WHERE id=?',[$name,$phone,$user['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['phone']=$phone;flash('success','Datos actualizados.');}
        redirect(url('account'));
    }
    $orderId=(int)($_GET['order']??0);layout_start('Mi cuenta');public_header();echo '<main class="section section-soft"><div class="container account-layout"><aside class="card admin-card account-nav"><h2>Mi cuenta</h2><p>'.e($user['name']).'<br><small class="muted">'.e($user['email']).'</small></p><a class="btn btn-light btn-block" href="'.url('account').'">Mis pedidos</a><form method="post" action="'.url('logout').'" style="margin-top:10px">'.csrf_field().'<button class="btn btn-light btn-block">Cerrar sesión</button></form></aside><section>';
    render_flashes();
    if($orderId){
        $order=$app->one('SELECT o.*,t.name tenant_name,t.slug tenant_slug,t.catalog_label FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE o.id=? AND o.user_id=?',[$orderId,$user['id']]);
        if(!$order){echo '<div class="card empty">Pedido no encontrado.</div>';}
        else{
            $items=$app->all('SELECT oi.*,p.status product_status,p.price current_price,p.sale_price current_sale_price,p.min_qty,p.qty_step FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id AND p.tenant_id=? WHERE oi.order_id=? ORDER BY oi.id',[$order['tenant_id'],$orderId]);$repeat=[];
            foreach($items as $item){$repeatItem=repeat_order_item_v5($app,$item,(int)$order['tenant_id']);if($repeatItem)$repeat[]=$repeatItem;}
            echo '<p><a class="btn btn-light" href="'.url('account').'">← Mis pedidos</a></p><article class="card admin-card"><div class="section-head"><div><span class="tag">'.e($order['status']).'</span><h1>Pedido #'.e($order['order_number']).'</h1><p class="muted">'.e($order['tenant_name']).' · '.e(date('d/m/Y H:i',strtotime($order['created_at']))).'</p></div><strong class="total">'.money((float)$order['total']).'</strong></div><div class="order-delivery-data"><p><strong>Entrega:</strong> '.e($order['delivery_type']).(!empty($order['scheduled_at'])?' · Programado '.e(date('d/m/Y H:i',strtotime($order['scheduled_at']))):'').'</p>'.(!empty($order['address'])?'<p><strong>Dirección:</strong> '.nl2br(e($order['address'])).(!empty($order['address_reference'])?'<br><strong>Referencia:</strong> '.nl2br(e($order['address_reference'])):'').'</p>':'').'</div><div class="table-wrap"><table class="table"><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Total</th></tr>';
            foreach($items as $item)echo '<tr><td>'.e($item['product_name']).order_item_details_html($item).'</td><td>'.e($item['quantity']).' '.e($item['unit_label']).'</td><td>'.money((float)$item['unit_price']).'</td><td>'.money((float)$item['line_subtotal']+(float)$item['line_tax']).'</td></tr>';
            echo '</table></div><div class="order-totals"><p>Subtotal <strong>'.money((float)$order['subtotal']).'</strong></p><p>IVA <strong>'.money((float)$order['tax_total']).'</strong></p><p>Descuento <strong>-'.money((float)$order['discount_total']).'</strong></p><p>Entrega <strong>'.money((float)$order['delivery_total']).'</strong></p></div>';
            if($repeat){$payload=json_encode(['tenant'=>$order['tenant_slug'],'catalog'=>url($order['tenant_slug'].'/'.catalog_segment($order)),'items'=>$repeat],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);echo '<button class="btn btn-accent" data-repeat-order=\''.e($payload).'\'>Repetir pedido</button>';}
            echo '</article>';
        }
    }else{
        $orders=$app->all('SELECT o.id,o.order_number,o.total,o.status,o.created_at,t.name tenant_name FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE o.user_id=? ORDER BY o.created_at DESC LIMIT 100',[$user['id']]);
        echo '<section class="card admin-card"><h1>Mis pedidos</h1><div class="table-wrap"><table class="table"><tr><th>Pedido</th><th>Negocio</th><th>Total</th><th>Estado</th><th>Fecha</th><th></th></tr>';foreach($orders as $order)echo '<tr><td>#'.e($order['order_number']).'</td><td>'.e($order['tenant_name']).'</td><td>'.money((float)$order['total']).'</td><td><span class="status">'.e($order['status']).'</span></td><td>'.e(date('d/m/Y',strtotime($order['created_at']))).'</td><td><a class="btn btn-light" href="?order='.(int)$order['id'].'">Ver detalle</a></td></tr>';if(!$orders)echo '<tr><td colspan="6">Todavía no tienes pedidos.</td></tr>';echo '</table></div></section><section class="card admin-card" style="margin-top:20px"><h2>Datos de mi cuenta</h2><form method="post">'.csrf_field().field('Nombre','name',$user['name'],true).field('Teléfono','phone',$user['phone'],true).field('Correo','email',$user['email'],false,'email').'<small class="muted">El correo de acceso no se modifica desde este formulario.</small><button class="btn" style="margin-top:14px">Guardar datos</button></form></section>';
    }
    echo '</section></div></main>';public_footer();layout_end();
}

function public_footer(array $t=null):void{global $app;$isStore=!empty($t['slug']);if($isStore)$t['official_logo']=$t['logo']??'';if(!$t&&isset($app))$t=['name'=>$app->setting('site_name','FISITAPP'),'official_logo'=>$app->setting('platform_logo',url('assets/fisitapp-logo.webp')),'phone'=>$app->setting('master_whatsapp','8676-1771'),'facebook_url'=>$app->setting('facebook_url'),'instagram_url'=>$app->setting('instagram_url'),'tiktok_url'=>$app->setting('tiktok_url'),'footer_text'=>$app->setting('footer_text','Una experiencia de compra rápida, clara y cercana.'),'footer_links_title'=>$app->setting('footer_links_title','Enlaces'),'footer_contact_title'=>$app->setting('footer_contact_title','Contacto'),'footer_credit'=>$app->setting('footer_credit','Creado por Fisital Multiservicios')];echo '<footer class="footer"><div class="container footer-grid"><div>'.(!empty($t['official_logo'])?'<div class="footer-logo-wrap"><img class="footer-logo" src="'.e($t['official_logo']).'" alt="'.e($t['name']??'FISITAAP').'"></div>':'<div class="brand" style="color:#fff">'.($isStore?'':'<span class="brand-mark">F</span>').e($t['name']??'FISITAPP').'</div>').'<p>'.e($t['footer_text']??'Una experiencia de compra rápida, clara y cercana.').'</p>'.(!empty($t['business_hours'])?'<p>'.nl2br(e($t['business_hours'])).'</p>':'').'</div><div><strong>'.e($t['footer_links_title']??'Enlaces').'</strong><p><a href="'.($isStore?url($t['slug']):url()).'">Inicio</a></p><p><a href="'.($isStore?url($t['slug'].'/blog'):url('blog')).'">Blog</a></p>'.($isStore?'<p><a class="footer-sales-link" href="'.url().'"><img src="'.e($app->setting('platform_logo',url('assets/fisitapp-logo.webp'))).'" alt="FISITAAP" style="width:110px;max-height:40px;object-fit:contain;display:block;margin-bottom:10px">¿Quieres vender en línea?</a></p>':'').'</div><div><strong>'.e($t['footer_contact_title']??'Contacto').'</strong><p>'.e($t['phone']??'8676-1771').'</p><div class="socials">';foreach(['facebook_url'=>'f','instagram_url'=>'◎','tiktok_url'=>'♪'] as $key=>$icon)if(!empty($t[$key]))echo '<a class="social" target="_blank" rel="noopener noreferrer" href="'.e($t[$key]).'">'.$icon.'</a>';echo '</div></div></div><div class="container footer-credit">'.e($t['footer_credit']??'Creado por Fisital Multiservicios').' · '.date('Y').'</div></footer>';}
function render_flashes():void{foreach(flashes() as [$type,$msg])echo '<div class="alert alert-'.e($type).'">'.e($msg).'</div>';}
function simple_error(string $title,string $text):void{layout_start($title);echo '<main class="auth-page"><section class="card auth-card"><h1>'.e($title).'</h1><p class="muted">'.e($text).'</p><a class="btn" href="'.url().'">Volver al inicio</a></section></main>';layout_end();}
